import React, { useEffect, useMemo, useState } from "react";
import DashboardLayout from "../components/DashboardLayout";
import SearchBar from "../components/SearchBar";
import Table from "../components/Table";
import api from "../services/api";

const Teachers = () => {
  const [teachers, setTeachers] = useState([]);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [form, setForm] = useState({ name: "", email: "", password: "" });

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    const fetchTeachers = async () => {
      const response = await api.get(`/admin/teachers?search=${encodeURIComponent(debouncedSearch)}`);
      setTeachers(response.data.teachers);
    };
    fetchTeachers();
  }, [debouncedSearch]);

  const onChange = (event) => {
    setForm((prev) => ({ ...prev, [event.target.name]: event.target.value }));
  };

  const addTeacher = async (event) => {
    event.preventDefault();
    if (!form.name || !form.email || !form.password) {
      return;
    }
    await api.post("/admin/add-teacher", form);
    setForm({ name: "", email: "", password: "" });
    const response = await api.get(`/admin/teachers?search=${encodeURIComponent(debouncedSearch)}`);
    setTeachers(response.data.teachers);
  };

  const rows = useMemo(
    () => teachers.map((teacher) => [teacher.name, teacher.email, teacher.role]),
    [teachers]
  );

  return (
    <DashboardLayout title="Teachers">
      <div className="panel">
        <SearchBar value={search} onChange={setSearch} placeholder="Search..." />
      </div>
      <div className="panel">
        <h3>Add Teacher</h3>
        <form className="grid-form" onSubmit={addTeacher}>
          <input name="name" value={form.name} onChange={onChange} placeholder="Teacher Name" />
          <input name="email" value={form.email} onChange={onChange} placeholder="Teacher Email" type="email" />
          <input name="password" value={form.password} onChange={onChange} placeholder="Password" type="password" />
          <button type="submit">Add Teacher</button>
        </form>
      </div>
      <Table headers={["Name", "Email", "Role"]} rows={rows} />
    </DashboardLayout>
  );
};

export default Teachers;
